def strip_stress(phoneme):
    base = phoneme.rstrip("012")
    tail = phoneme[len(base):]
    return base, (int(tail) if tail else None)


def stress_of(phoneme):
    return strip_stress(phoneme)[1]


def features(phoneme, table):
    base, _ = strip_stress(phoneme)
    if base not in table:
        raise ValueError(f"unknown phoneme {phoneme!r}")
    return table[base][1:]


def feature_distance(a, b, table):
    left = features(a, table)
    right = features(b, table)
    if strip_stress(a)[0] == strip_stress(b)[0]:
        return 0.0
    differing = sum(1 for x, y in zip(left, right) if x != y)
    return differing / len(left)


def phonetic_distance(source, target, table):
    rows = len(source) + 1
    cols = len(target) + 1
    dp = [[0.0] * cols for _ in range(rows)]
    for i in range(rows):
        dp[i][0] = float(i)
    for j in range(cols):
        dp[0][j] = float(j)
    for i in range(1, rows):
        for j in range(1, cols):
            dp[i][j] = min(
                dp[i - 1][j] + 1.0,
                dp[i][j - 1] + 1.0,
                dp[i - 1][j - 1] + feature_distance(source[i - 1], target[j - 1],
                                                    table),
            )
    return dp[-1][-1]


def is_minimal_pair(source, target, table):
    if len(source) != len(target):
        return False
    differing = [index for index, (a, b) in enumerate(zip(source, target))
                 if strip_stress(a)[0] != strip_stress(b)[0]]
    if len(differing) != 1:
        return False
    features(source[differing[0]], table)
    features(target[differing[0]], table)
    return True


def lookup(word, lexicon, fallback=None):
    key = word.lower()
    if key in lexicon:
        return [list(pronunciation) for pronunciation in lexicon[key]]
    if fallback is None:
        raise KeyError(f"{word!r} is not in the lexicon and there is no fallback")
    return [list(fallback(word))]
